problems.statement:
Construct a $4\times 4$ grid of digits chosen from 1,2,3,4 such that all four digits appear in <br>(i) each of the four rows, <br>(ii) each of the four columns, <br>(iii) each of the two diagonals,<br> (iv) each of the four corner $2\times 2$ grids.<br>
<script>
(function(){
  var SIZE = 4, CELL = 'width:42px;height:42px;text-align:center;font-size:18px;font-family:Consolas,monospace;border:1px solid var(--border-color);border-radius:4px;background:var(--card-bg);color:var(--text-primary);outline:none;';
  // 等 DOM 就绪（innerHTML 注入时可能还没挂到文档里）
  function boot(){
    var tg = document.getElementById('textAnswerGroup'),
        inp = document.getElementById('answerInput'),
        btn = document.getElementById('checkAnswerBtn');
    if(!tg || !inp || !btn || document.getElementById('gridInput4x4')) return false;
    tg.querySelector('label') && (tg.querySelector('label').style.display='none');
    inp.style.display='none'; btn.style.display='none';
    var wrap = document.createElement('div'); wrap.id='gridInput4x4';
    wrap.style.cssText='margin:.6rem 0;';
    var h='<table style="border-collapse:separate;border-spacing:4px;margin:0 auto;">';
    for(var r=0;r<SIZE;r++){h+='<tr>';for(var c=0;c<SIZE;c++)h+='<td style="padding:0;"><input type="text" maxlength="1" inputmode="numeric" data-r="'+r+'" data-c="'+c+'" style="'+CELL+'"></td>';h+='</tr>';}
    h+='</table><div style="margin-top:.7rem;text-align:center;"><button type="button" id="gridSubmitBtn" class="check-btn">Submit</button></div>';
    wrap.innerHTML=h; tg.appendChild(wrap);
    var cell=function(r,c){return wrap.querySelector('input[data-r="'+r+'"][data-c="'+c+'"]');};
    wrap.querySelectorAll('input').forEach(function(el){
      el.addEventListener('input',function(){el.value=el.value.replace(/\D/g,'').slice(-1);});
      el.addEventListener('keydown',function(e){
        var r=+el.dataset.r,c=+el.dataset.c,nr=r,nc=c;
        if(e.key==='ArrowUp')nr--;else if(e.key==='ArrowDown')nr++;
        else if(e.key==='ArrowLeft')nc--;else if(e.key==='ArrowRight')nc++;else return;
        e.preventDefault();var t=cell(Math.max(0,Math.min(SIZE-1,nr)),Math.max(0,Math.min(SIZE-1,nc)));
        t&&(t.focus(),t.select());
      });
    });
    cell(0,0).focus();
    wrap.querySelector('#gridSubmitBtn').addEventListener('click',function(){
      var p=[];
      for(var r=0;r<SIZE;r++)for(var c=0;c<SIZE;c++){var v=(cell(r,c).value||'').trim();p.push(v||'X');}
      inp.value=p.join('|');
      btn.dispatchEvent(new MouseEvent('mousedown',{bubbles:true,cancelable:true}));
    });
    return true;
  }
  // 注入时可能还没挂载，轮询几次
  if(!boot()){var n=0,t=setInterval(function(){if(boot()||++n>20)clearInterval(t);},100);}
})();
</script>
